package com.northstar.crm.config;

import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Component public class DemoDataInitializer implements ApplicationRunner {
 private final UserRepository users;private final OrganizationRepository orgs;private final ContactRepository contacts;private final DealRepository deals;private final EscalationRepository escalations;private final CommentRepository comments;private final DocumentRepository docs;private final ApiCredentialRepository keys;private final WebhookRepository hooks;private final WebhookDeliveryRepository deliveries;private final AuditRepository audits;private final NotificationRepository notifications;private final PlanRepository plans;private final PasswordEncoder encoder;private final Path storage;
 public DemoDataInitializer(UserRepository users,OrganizationRepository orgs,ContactRepository contacts,DealRepository deals,EscalationRepository escalations,CommentRepository comments,DocumentRepository docs,ApiCredentialRepository keys,WebhookRepository hooks,WebhookDeliveryRepository deliveries,AuditRepository audits,NotificationRepository notifications,PlanRepository plans,PasswordEncoder encoder,@Value("${app.storage-path}")String storage){this.users=users;this.orgs=orgs;this.contacts=contacts;this.deals=deals;this.escalations=escalations;this.comments=comments;this.docs=docs;this.keys=keys;this.hooks=hooks;this.deliveries=deliveries;this.audits=audits;this.notifications=notifications;this.plans=plans;this.encoder=encoder;this.storage=Path.of(storage).toAbsolutePath().normalize();}
 @Override @Transactional public void run(ApplicationArguments args)throws Exception {if(users.count()>0)return;Files.createDirectories(storage);var password=encoder.encode("DemoPass123!");var admin=users.save(new UserAccount("admin@northstar.local","Amara Shah",password,Role.PLATFORM_ADMIN,null));var system=users.save(new UserAccount("system@northstar.local","Northstar Scheduler",password,Role.PLATFORM_ADMIN,null));system.setEnabled(false);var am1=users.save(new UserAccount("manager@northstar.local","Theo Morgan",password,Role.ACCOUNT_MANAGER,null));var am2=users.save(new UserAccount("manager2@northstar.local","Nadia Okafor",password,Role.ACCOUNT_MANAGER,null));var team=UUID.randomUUID();var support=users.save(new UserAccount("support@northstar.local","Lina Chen",password,Role.SUPPORT_AGENT,null));support.setTeamId(team);var support2=users.save(new UserAccount("support2@northstar.local","Marcus Bell",password,Role.SUPPORT_AGENT,null));support2.setTeamId(team);
 plans.saveAll(List.of(new PlanDefinition("Launch",new BigDecimal("499.00"),"GBP",120,10),new PlanDefinition("Scale",new BigDecimal("1299.00"),"GBP",600,50),new PlanDefinition("Enterprise",new BigDecimal("3499.00"),"GBP",2400,250)));
 var names=List.of("Aster & Co","Beacon Freight","Cedar Health Labs","Driftline Energy","Elmbridge Legal","Fable Commerce","Granite Works","Harbour Analytics");var planNames=List.of("Enterprise","Scale","Scale","Launch","Enterprise","Launch","Scale","Enterprise");var healths=List.of(Health.EXCELLENT,Health.GOOD,Health.WATCH,Health.CRITICAL,Health.GOOD,Health.WATCH,Health.EXCELLENT,Health.CRITICAL);var statuses=List.of(OrganizationStatus.ACTIVE,OrganizationStatus.ACTIVE,OrganizationStatus.AT_RISK,OrganizationStatus.AT_RISK,OrganizationStatus.ACTIVE,OrganizationStatus.ONBOARDING,OrganizationStatus.ACTIVE,OrganizationStatus.SUSPENDED);var scores=List.of(94,82,61,34,77,58,91,28);var organizations=new ArrayList<Organization>();for(int i=0;i<8;i++){var owner=i%2==0?am1:am2;organizations.add(orgs.save(new Organization(names.get(i),planNames.get(i),statuses.get(i),healths.get(i),scores.get(i),owner.getId(),LocalDate.now().plusDays(24+i*31),"billing"+(i+1)+"@example.test",i%3==0?"Executive sponsor engagement has softened; confirm success plan before commercial review.":"Adoption trend is stable; maintain cadence and validate renewal stakeholders.")));}
 var customer=users.save(new UserAccount("customer@aster.example","Priya Nair",password,Role.CUSTOMER_CONTACT,organizations.get(0).getId()));var customer2=users.save(new UserAccount("customer2@beacon.example","Owen Price",password,Role.CUSTOMER_CONTACT,organizations.get(1).getId()));
 for(int i=0;i<24;i++){var org=organizations.get(i%8);contacts.save(new Contact(org.getId(),List.of("Alex","Sam","Jordan","Casey","Morgan","Riley").get(i%6)+" "+(char)('A'+i)+".","contact"+(i+1)+"@example.test","+44 20 7946 "+String.format("%04d",1000+i),List.of("Operations Director","Security Lead","Finance Manager","Product Owner").get(i%4),i%7==0,i%3!=0));}
 var stages=List.of(DealStage.LEAD,DealStage.QUALIFIED,DealStage.PROPOSAL,DealStage.NEGOTIATION,DealStage.CLOSED_WON,DealStage.CLOSED_LOST,DealStage.RENEWAL_PENDING);for(int i=0;i<14;i++){var d=deals.save(new Deal(organizations.get(i%8).getId(),i<8?"FY27 renewal":"Expansion · "+List.of("Analytics","Seats","Compliance").get(i%3),DealStage.LEAD,new BigDecimal(18000+i*3750+".00"),35+(i%6)*10,LocalDate.now().plusDays(35+i*12),"Commercial assumptions reviewed against the seeded plan schedule."));advanceDeal(system,d,stages.get(i%stages.size()));}
 var severities=Severity.values();var escStatuses=List.of(EscalationStatus.OPEN,EscalationStatus.WAITING_ON_CUSTOMER,EscalationStatus.WAITING_ON_INTERNAL,EscalationStatus.RESOLVED,EscalationStatus.CLOSED);for(int i=0;i<16;i++){var e=escalations.save(new Escalation(organizations.get(i%8).getId(),List.of("SSO provisioning delay","Invoice reconciliation","Data export timing","Webhook delivery retries","Onboarding milestone blocked").get(i%5)+" #"+(i+1),severities[i%4],i%2==0?support.getId():support2.getId(),team,"We are tracking the issue and will share the next confirmed action in this thread."));advanceEscalation(system,e,escStatuses.get(i%5));comments.save(new EscalationComment(e.getId(),support.getId(),false,"Initial triage completed. The next checkpoint is scheduled with the customer team."));comments.save(new EscalationComment(e.getId(),support.getId(),true,"Internal owner confirmed. Avoid sharing infrastructure identifiers externally."));}
 for(int i=0;i<12;i++){var org=organizations.get(i%8);var content=("Northstar demo "+List.of("contract","security questionnaire","invoice","onboarding plan").get(i%4)+" for "+org.getName()+". Mock data only.\n").getBytes(StandardCharsets.UTF_8);var stored=UUID.randomUUID()+".txt";Files.write(storage.resolve(stored),content,StandardOpenOption.CREATE_NEW);docs.save(new CustomerDocument(org.getId(),admin.getId(),List.of("Service agreement","Security review","Invoice statement","Onboarding plan").get(i%4)+" · "+org.getName()+".txt",stored,"text/plain",content.length,DocumentCategory.values()[i%4],i%3==0?Visibility.CUSTOMER_VISIBLE:(i%3==1?Visibility.INTERNAL:Visibility.BILLING_ONLY),"seeded,verified"));}
 for(int i=0;i<4;i++){var raw="nsk_seed"+i+"_demo_key_not_for_production";var k=keys.save(new ApiCredential(organizations.get(i).getId(),"Production reporting",raw.substring(0,12),encoder.encode(raw),"organizations:read,escalations:read",Instant.now().plusSeconds(31536000)));if(i==3){k.revoke();audits.save(new AuditEvent(system.getId(),"API_KEY_REVOKED","ApiCredential",k.getId(),"status=ACTIVE","status=REVOKED","seed lifecycle action"));}}
 for(int i=0;i<3;i++){var h=hooks.save(new WebhookEndpoint(organizations.get(i).getId(),List.of("Billing ops","Customer data","Incident desk").get(i),"https://"+List.of("billing","data","incidents").get(i)+".example.test/events","ESCALATION_UPDATED,RENEWAL_DUE",encoder.encode("seed-webhook-secret-"+i)));deliveries.save(new WebhookDelivery(h.getId(),h.getUrl(),"ESCALATION_UPDATED","DELIVERED","Local provider mock accepted event (HTTP 202)"));}
 notifications.saveAll(List.of(new Notification(am1.getId(),"Renewal plan needs review",organizations.get(2).getName()+" is in Watch health","organizations/"+organizations.get(2).getId()),new Notification(support.getId(),"Critical escalation assigned","Review the latest internal handover","escalations"),new Notification(customer.getId(),"New shared document","A service agreement is available","organizations/"+organizations.get(0).getId())));audits.save(new AuditEvent(system.getId(),"DEMO_DATA_LOADED","Platform",null,"{}","organizations=8,contacts=24,deals=14,escalations=16,documents=12","local bootstrap job"));}
 private void advanceDeal(UserAccount actor,Deal d,DealStage target){var path=switch(target){case LEAD->List.<DealStage>of();case QUALIFIED->List.of(DealStage.QUALIFIED);case PROPOSAL->List.of(DealStage.QUALIFIED,DealStage.PROPOSAL);case NEGOTIATION->List.of(DealStage.QUALIFIED,DealStage.PROPOSAL,DealStage.NEGOTIATION);case CLOSED_WON->List.of(DealStage.QUALIFIED,DealStage.PROPOSAL,DealStage.NEGOTIATION,DealStage.CLOSED_WON);case CLOSED_LOST->List.of(DealStage.CLOSED_LOST);case RENEWAL_PENDING->List.of(DealStage.QUALIFIED,DealStage.PROPOSAL,DealStage.NEGOTIATION,DealStage.CLOSED_WON,DealStage.RENEWAL_PENDING);};for(var next:path){var before=d.getStage();d.transition(next);audits.save(new AuditEvent(actor.getId(),"DEAL_STAGE_CHANGED","Deal",d.getId(),"stage="+before,"stage="+next,"seed workflow edge"));}}
 private void advanceEscalation(UserAccount actor,Escalation e,EscalationStatus target){var path=switch(target){case OPEN->List.<EscalationStatus>of();case WAITING_ON_CUSTOMER->List.of(EscalationStatus.WAITING_ON_CUSTOMER);case WAITING_ON_INTERNAL->List.of(EscalationStatus.WAITING_ON_INTERNAL);case RESOLVED->List.of(EscalationStatus.RESOLVED);case CLOSED->List.of(EscalationStatus.RESOLVED,EscalationStatus.CLOSED);};for(var next:path){var before=e.getStatus();e.transition(next);audits.save(new AuditEvent(actor.getId(),"ESCALATION_STATUS_CHANGED","Escalation",e.getId(),"status="+before,"status="+next,"seed workflow edge"));}}
}
